programs:
{
  "spec_version": 1.0,
  "title": "Tính khoảng cách từ N đến mặt phẳng (OAB)",
  "description": "Bài toán này minh họa cách tính khoảng cách từ một điểm đến một mặt phẳng trong không gian Oxyz, sử dụng các phép dựng hình cơ bản.",
  "memory_declarations": [
    {
      "name": "O",
      "type": "point3"
    },
    {
      "name": "A",
      "type": "point3"
    },
    {
      "name": "B",
      "type": "point3"
    },
    {
      "name": "C",
      "type": "point3"
    },
    {
      "name": "M",
      "type": "point3"
    },
    {
      "name": "N",
      "type": "point3"
    },
    {
      "name": "plane_OAB",
      "type": "plane3"
    },
    {
      "name": "distance_N_to_OAB",
      "type": "float"
    }
  ],
  "statements": [
    {
      "kind": "declare_point",
      "target_var": "O",
      "at": [0, 0, 0],
      "model_assumption": "Chọn O làm gốc tọa độ"
    },
    {
      "kind": "declare_point",
      "target_var": "A",
      "at": [2, 0, 0],
      "model_assumption": "Đặt OA dọc theo trục x, OA = 2"
    },
    {
      "kind": "declare_point",
      "target_var": "B",
      "at": [0, 2, 0],
      "model_assumption": "Đặt OB dọc theo trục y, OB = 2, vuông góc với OA"
    },
    {
      "kind": "declare_point",
      "target_var": "C",
      "at": [0, 0, 2],
      "model_assumption": "Đặt OC dọc theo trục z, OC = 2, vuông góc với OA và OB"
    },
    {
      "kind": "assign",
      "target_var": "M",
      "expr": {
        "kind": "midpoint",
        "a": "B",
        "b": "C"
      },
      "label": "M là trung điểm của BC"
    },
    {
      "kind": "assign",
      "target_var": "N",
      "expr": {
        "kind": "midpoint",
        "a": "O",
        "b": "M"
      },
      "label": "N là trung điểm của OM"
    },
    {
      "kind": "construct_plane",
      "target_var": "plane_OAB",
      "through": ["O", "A", "B"],
      "label": "Mặt phẳng (OAB)"
    },
    {
      "kind": "assign",
      "target_var": "distance_N_to_OAB",
      "expr": {
        "kind": "measure",
        "quantity": "distance",
        "of": "N",
        "wrt": "plane_OAB"
      },
      "label": "Khoảng cách từ N đến mặt phẳng (OAB)"
    }
  ],
  "pedagogical_intent": "Bài toán này giúp học sinh thực hành xác định tọa độ các điểm trong không gian khi biết các quan hệ vuông góc và độ dài, sau đó áp dụng công thức trung điểm và tính khoảng cách từ điểm đến mặt phẳng."
}

{
  "spec_version": 1.0,
  "title": "Tính côsin góc giữa hai đường thẳng trong lăng trụ đứng",
  "description": "Bài toán này minh họa cách xác định góc giữa hai đường thẳng chéo nhau trong không gian bằng cách sử dụng hệ tọa độ và các phép dựng hình cơ bản.",
  "memory_declarations": [
    {
      "name": "A",
      "type": "point3"
    },
    {
      "name": "B",
      "type": "point3"
    },
    {
      "name": "C",
      "type": "point3"
    },
    {
      "name": "A_prime",
      "type": "point3"
    },
    {
      "name": "B_prime",
      "type": "point3"
    },
    {
      "name": "C_prime",
      "type": "point3"
    },
    {
      "name": "AB_prime_line",
      "type": "line3"
    },
    {
      "name": "BC_prime_line",
      "type": "line3"
    },
    {
      "name": "cos_sq_angle_AB_prime_BC_prime",
      "type": "float"
    }
  ],
  "statements": [
    {
      "kind": "declare_point",
      "target_var": "A",
      "at": [0, 0, 0],
      "model_assumption": "Chọn A làm gốc tọa độ (0,0,0) vì đáy vuông tại A và lăng trụ đứng."
    },
    {
      "kind": "declare_point",
      "target_var": "B",
      "at": [2, 0, 0],
      "model_assumption": "Đặt AB dọc theo trục x, với AB = 2."
    },
    {
      "kind": "declare_point",
      "target_var": "C",
      "at": [0, 2, 0],
      "model_assumption": "Đặt AC dọc theo trục y, với AC = 2 và vuông góc với AB."
    },
    {
      "kind": "declare_point",
      "target_var": "A_prime",
      "at": [0, 0, 2],
      "model_assumption": "Đặt AA' dọc theo trục z, với AA' = 2 vì lăng trụ đứng."
    },
    {
      "kind": "declare_point",
      "target_var": "B_prime",
      "at": [2, 0, 2],
      "model_assumption": "Xác định B' dựa trên A, B, A' (B' có cùng tọa độ x, y với B và z với A')."
    },
    {
      "kind": "declare_point",
      "target_var": "C_prime",
      "at": [0, 2, 2],
      "model_assumption": "Xác định C' dựa trên A, C, A' (C' có cùng tọa độ x, y với C và z với A')."
    },
    {
      "kind": "construct_line",
      "target_var": "AB_prime_line",
      "through_a": "A",
      "through_b": "B_prime",
      "label": "Đường thẳng AB'"
    },
    {
      "kind": "construct_line",
      "target_var": "BC_prime_line",
      "through_a": "B",
      "through_b": "C_prime",
      "label": "Đường thẳng BC'"
    },
    {
      "kind": "assign",
      "target_var": "cos_sq_angle_AB_prime_BC_prime",
      "expr": {
        "kind": "measure",
        "quantity": "angle_cos_sq",
        "of": "AB_prime_line",
        "wrt": "BC_prime_line"
      }
    }
  ],
  "pedagogical_intent": "Bài toán này giúp học sinh thực hành việc thiết lập hệ tọa độ cho các hình lăng trụ đứng và áp dụng công thức tính góc giữa hai đường thẳng trong không gian."
}

{
  "spec_version": 1.0,
  "title": "Khoảng cách từ đỉnh A đến đường thẳng BD trong hình hộp chữ nhật",
