      "name": "A",
      "type": "point3"
    },
    {
      "name": "B",
      "type": "point3"
    },
    {
      "name": "D",
      "type": "point3"
    },
    {
      "name": "line_BD",
      "type": "line3"
    },
    {
      "name": "distance_A_BD",
      "type": "float"
