}

{
  "spec_version": 1.0,
  "title": "Xác định thiết diện và tính khoảng cách từ đỉnh S đến mặt phẳng (P)",
  "description": "Bài toán này yêu cầu xác định thiết diện của hình chóp S.ABCD cắt bởi mặt phẳng (P) đi qua A, B và trung điểm M của SC, sau đó tính khoảng cách từ S đến (P).",
  "memory_declarations": [
    { "name": "A", "type": "point3" },
    { "name": "B", "type": "point3" },
    { "name": "C", "type": "point3" },
    { "name": "D", "type": "point3" },
    { "name": "S", "type": "point3" },
    { "name": "M", "type": "point3" },
    { "name": "N", "type": "point3" },
    { "name": "pyramid_S_ABCD", "type": "solid" },
    { "name": "P_plane", "type": "plane3" },
    { "name": "SD_line", "type": "line3" },
    { "name": "section_ABMN", "type": "polygon3" },
    { "name": "dist_S_P", "type": "float" }
  ],
  "statements": [
    {
      "kind": "declare_point",
      "target_var": "A",
      "at": [0, 0, 0],
      "model_assumption": "Chọn A làm gốc tọa độ"
    },
    {
      "kind": "declare_point",
      "target_var": "B",
      "at": [2, 0, 0],
      "model_assumption": "Đặt B trên trục x, cạnh hình vuông là 2"
    },
    {
      "kind": "declare_point",
      "target_var": "D",
      "at": [0, 2, 0],
      "model_assumption": "Đặt D trên trục y, cạnh hình vuông là 2"
    },
    {
      "kind": "declare_point",
      "target_var": "C",
      "at": [2, 2, 0],
      "model_assumption": "Xác định C từ A, B, D để tạo hình vuông"
    },
    {
      "kind": "declare_point",
      "target_var": "S",
      "at": [0, 0, 2],
      "model_assumption": "SA vuông góc đáy và SA = 2, nên S nằm trên trục z"
    },
    {
      "kind": "construct_solid",
      "target_var": "pyramid_S_ABCD",
      "vertices": ["S", "A", "B", "C", "D"],
      "faces": [
        ["A", "B", "C", "D"],
        ["S", "A", "B"],
        ["S", "B", "C"],
        ["S", "C", "D"],
        ["S", "D", "A"]
      ],
      "label": "Hình chóp S.ABCD"
    },
    {
      "kind": "assign",
      "target_var": "M",
      "expr": {
        "kind": "midpoint",
        "a": "S",
        "b": "C"
      },
      "label": "Trung điểm M của SC"
    },
    {
      "kind": "construct_plane",
      "target_var": "P_plane",
      "through": ["A", "B", "M"],
      "label": "Mặt phẳng (P) đi qua A, B, M"
    },
    {
      "kind": "construct_line",
      "target_var": "SD_line",
      "through_a": "S",
      "through_b": "D",
      "label": "Cạnh SD của hình chóp"
    },
    {
      "kind": "assign",
      "target_var": "N",
      "expr": {
        "kind": "intersect_line_plane",
        "line": "SD_line",
        "plane": "P_plane"
      },
      "label": "Giao điểm N của mặt phẳng (P) với cạnh SD"
    },
    {
      "kind": "construct_polygon",
      "target_var": "section_ABMN",
      "vertices": ["A", "B", "M", "N"],
      "label": "Thiết diện ABMN của hình chóp cắt bởi (P)"
    },
    {
      "kind": "assign",
      "target_var": "dist_S_P",
      "expr": {
        "kind": "measure",
        "quantity": "distance",
        "of": "S",
        "wrt": "P_plane"
      },
      "label": "Khoảng cách từ đỉnh S đến mặt phẳng (P)"
    }
  ],
  "pedagogical_intent": "Bài toán này minh họa cách xác định thiết diện của một khối đa diện bằng cách tìm các giao điểm của mặt phẳng cắt với các cạnh của khối, và cách tính khoảng cách từ một điểm đến một mặt phẳng."
}

{
  "spec_version": 1.0,
  "title": "Tính côsin góc giữa đường thẳng SC và mặt phẳng (ABC), và khoảng cách từ B đến mặt phẳng (SAC)",
  "description": "Bài toán này minh họa cách tính góc giữa đường thẳng và mặt phẳng, và khoảng cách từ điểm đến mặt phẳng trong không gian.",
  "memory_declarations": [
    {
      "name": "cos_angle_SC_ABC_sq",
      "type": "float",
      "model_assumption": "Giá trị cosin bình phương của góc giữa đường thẳng SC và mặt phẳng (ABC)"
    },
    {
      "name": "dist_B_SAC",
      "type": "float",
      "model_assumption": "Giá trị khoảng cách từ điểm B đến mặt phẳng (SAC)"
    }
  ],
  "statements": [
    {
      "kind": "declare_point",
      "target_var": "A",
      "at": [0, 0, 0],
      "model_assumption": "Chọn A làm gốc tọa độ (0,0,0) vì SA vuông góc với đáy ABC."
    },
    {
      "kind": "declare_point",
      "target_var": "B",
      "at": [2, 0, 0],
      "model_assumption": "Đặt B trên trục Ox, cách A 2 đơn vị, do AB=2 và tam giác ABC vuông tại B."
    },
    {
      "kind": "declare_point",
      "target_var": "C",
      "at": [2, 2, 0],
      "model_assumption": "Đặt C sao cho BC song song với trục Oy, cách B 2 đơn vị, do BC=2 và tam giác ABC vuông tại B."
    },
    {
      "kind": "declare_point",
      "target_var": "S",
      "at": [0, 0, 2],
      "model_assumption": "Đặt S trên trục Oz, cách A 2 đơn vị, do SA=2 và SA vuông góc với mặt phẳng đáy."
    },
    {
      "kind": "construct_line",
      "target_var": "SC_line",
      "through_a": "S",
      "through_b": "C",
      "label": "Đường thẳng SC"
    },
    {
      "kind": "construct_plane",
      "target_var": "ABC_plane",
      "through": ["A", "B", "C"],
      "label": "Mặt phẳng (ABC)"
    },
    {
      "kind": "construct_plane",
      "target_var": "SAC_plane",
      "through": ["S", "A", "C"],
      "label": "Mặt phẳng (SAC)"
    },
    {
      "kind": "assign",
      "target_var": "cos_angle_SC_ABC_sq",
      "expr": {
        "kind": "measure",
        "quantity": "angle_cos_sq",
        "of": "SC_line",
        "wrt": "ABC_plane"
      }
    },
    {
      "kind": "assign",
      "target_var": "dist_B_SAC",
      "expr": {
        "kind": "measure",
        "quantity": "distance",
        "of": "B",
        "wrt": "SAC_plane"
      }
    }
  ],
  "pedagogical_intent": "Bài toán này giúp học sinh thực hành xác định tọa độ các điểm trong không gian dựa trên các thông tin hình học cho trước, sau đó sử dụng các phép dựng hình cơ bản để tính toán các đại lượng như góc giữa đường thẳng và mặt phẳng, và khoảng cách từ điểm đến mặt phẳng."
}

